const D = { energy: .55, scale: 1, density: .5, speed: 1, wear: .45, hue: 8, x: .5, y: .46, style: 'persian', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A patterned woven carpet running away to the vanishing point — a repeating rug
// field of cusped medallions, a boteh lattice and guard borders, over a madder ground.
// The pile has a lean, so a drifting light reads as broad bright/dark bands sweeping the
// weave (the way a vacuum leaves tracks); the crushed pile down the middle is walked flat.
// Painted BELOW the horizon only. No textile floor exists in the catalog. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), wr = cl(P.wear,0,1), dn = cl(P.density,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', deco = sty==='deco', kilim = sty==='kilim', thread = sty==='threadbare';

const vy = cl(P.y,.18,.78)*height, vx = cl(P.x,.05,.95)*width;
const f = u*.92, H0 = 1;
const TU = .84*cl(P.scale,.35,2.6), TV = 1.14*cl(P.scale,.35,2.6);   // motif tile size (world)

if (S.z == null) S.z = 0;
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z += dt * P.speed * (.055 + .09*K.intensity) * (.5 + .7*en);
const zoff = S.z;

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
// pile-sheen light bands drifting on incommensurate rates (broad, carry the motion gate)
const shA = 1.8*Math.sin(tt*.061) + .9*Math.sin(tt*.151+1.2);
const shB = -1.5*Math.sin(tt*.043+2.1) - .8*Math.sin(tt*.113+.5);
const glow = (.4+.6*en)*(.55+.5*K.intensity) + bass*.2;

// palette: ground, motif-light (ivory), motif-mid (indigo/teal), accent, border
let cg, cml, cmm, cac, cbd;
if (bp)         { cg=[212,80,9]; cml=[190,40,70]; cmm=[200,60,26]; cac=[186,52,84]; cbd=[214,84,6]; }
else if (deco)  { cg=[Hh,20,16]; cml=[44,44,86]; cmm=[186,40,50]; cac=[44,60,78]; cbd=[Hh,30,10]; }
else if (kilim) { cg=[Hh+6,58,44]; cml=[40,26,84]; cmm=[28,64,58]; cac=[150,40,52]; cbd=[Hh-6,60,26]; }
else if (thread){ cg=[Hh+4,26,40]; cml=[40,10,78]; cmm=[210,20,42]; cac=[36,24,64]; cbd=[Hh,24,26]; }
else            { cg=[Hh,66,46]; cml=[40,18,88]; cmm=[224,54,40]; cac=[40,64,76]; cbd=[222,58,24]; }
const G  = hsv(cg[0],cg[1]/100,cg[2]/100);
const ML = hsv(cml[0],cml[1]/100,cml[2]/100);
const MM = hsv(cmm[0],cmm[1]/100,cmm[2]/100);
const AC = hsv(cac[0],cac[1]/100,cac[2]/100);
const BD = hsv(cbd[0],cbd[1]/100,cbd[2]/100);

const BW = Math.max(360,Math.min(720,Math.round(width/2.4))), BH = Math.max(44, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const AL = P.alpha/100;
const j0 = Math.max(0, Math.floor((vy/height)*BH));
for (let j=0;j<j0;j++) for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0;

// cusped-diamond medallion mask in symmetric tile coords (su,sv in 0..1 from centre)
function medallion(su,sv){
  const cusp = 1 + .16*Math.cos(8*Math.atan2(sv+1e-4, su+1e-4));
  const rr = (su*su + sv*sv*.86);
  return cl((.30*cusp - rr)/.30, 0, 1);
}

for (let j=j0;j<BH;j++){
  const sy = (j+.5)/BH*height, dy = sy - vy;
  if (dy < .35){ for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0; continue; }
  const Z = f*H0/dy, wz = Z + zoff;
  const far = cl((Z-1.1)/9, 0, 1);
  const det = cl(1 - far*1.05, .05, 1);
  for (let i=0;i<BW;i++){
    const sx = (i+.5)/BW*width, X = (sx-vx)*Z/f;
    const o = 4*(j*BW+i);
    // ---- rug coordinates: tile + local, folded to 4-fold symmetry ----
    const uu = X/TU + 100, vv = wz/TV + 100;
    const fu = uu - Math.floor(uu), fv = vv - Math.floor(vv);
    const su = Math.abs(fu-.5)*2, sv = Math.abs(fv-.5)*2;     // 0 centre -> 1 edge
    // guard border between tiles
    const bord = cl((Math.max(su,sv)-.80)/.20, 0, 1);
    const bordIn = cl((Math.max(su,sv)-.70)/.06,0,1)*(1-cl((Math.max(su,sv)-.80)/.02,0,1));
    // central medallion + surrounding field lattice (boteh diamonds)
    const med = medallion(su,sv);
    const medRing = cl(1-Math.abs(med-.5)/.10,0,1);
    const latU = Math.abs(((fu*3+.5)%1)-.5)*2, latV = Math.abs(((fv*3+.5)%1)-.5)*2;
    const boteh = cl(1-(latU*latU+latV*latV)/.16,0,1) * (1-med) * (1-bord);
    const botehRing = cl(1-Math.abs((latU*latU+latV*latV)-.10)/.05,0,1)*(1-med)*(1-bord);
    // ---- assemble region colour ----
    let r=G[0], g2=G[1], b2=G[2];
    // field fill motifs
    r+=(MM[0]-r)*boteh*.9; g2+=(MM[1]-g2)*boteh*.9; b2+=(MM[2]-b2)*boteh*.9;
    r+=(ML[0]-r)*botehRing*.8; g2+=(ML[1]-g2)*botehRing*.8; b2+=(ML[2]-b2)*botehRing*.8;
    // medallion
    r+=(MM[0]-r)*med*.85; g2+=(MM[1]-g2)*med*.85; b2+=(MM[2]-b2)*med*.85;
    r+=(AC[0]-r)*medRing*.9; g2+=(AC[1]-g2)*medRing*.9; b2+=(AC[2]-b2)*medRing*.9;
    // border band + guard stripe
    r+=(BD[0]-r)*bord*.92; g2+=(BD[1]-g2)*bord*.92; b2+=(BD[2]-b2)*bord*.92;
    r+=(ML[0]-r)*bordIn*.7; g2+=(ML[1]-g2)*bordIn*.7; b2+=(ML[2]-b2)*bordIn*.7;
    // ---- pile weave: fine warp/weft texture so nothing is a flat fill ----
    const warp = Math.sin(X*430) , weft = Math.sin(wz*430);
    const weave = (.5+.5*warp*weft)*det + (1-det)*.5;
    // knot noise breaks the pattern into hand-knotted grain
    const knot = vn(X*140+7.3, wz*140)*det + (1-det)*.5;
    // ---- pile sheen: drifting broad light bands (the motion) + per-tile lean two-tone ----
    const lean = ((Math.floor(uu)+Math.floor(vv))&1) ? 1 : -1;
    const band = Math.exp(-Math.pow((X-shA)/2.2,2))*1.0 + Math.exp(-Math.pow((X-shB)/2.8,2))*.7;
    const sheen = .70 + .30*lean*Math.sin(wz*2.4 - X*.6) + band*glow*.5*(kilim?.4:1);
    // wear: pile walked flat down the middle -> lighter, matted
    const lane = cl(1-Math.abs(X)/(.55+ .3*Math.sin(wz*.3)),0,1)*wr;
    let lum = (.72 + .46*weave*(kilim?.35:.7)) * sheen * (kilim?1:(.95+knot*.36));
    lum *= 1 + lane*.35; lum -= lane*.06;
    lum = cl(lum,0,1.7);
    r*=lum; g2*=lum; b2*=lum;
    // matte the crushed lane (desaturate toward grey)
    if (lane>0){ const gy=(r+g2+b2)/3; r+=(gy-r)*lane*.35; g2+=(gy-g2)*lane*.35; b2+=(gy-b2)*lane*.35; }
    if (thread){ // holes worn through to the jute backing
      const hole = cl((vn(X*10+3.1,wz*10)-.62)*4.0,0,1)*wr;
      const jb=hsv(34,.30,.28); r+=(jb[0]-r)*hole; g2+=(jb[1]-g2)*hole; b2+=(jb[2]-b2)*hole;
    }
    if (bp){
      const line = cl(medRing+botehRing+bord*.6+bordIn,0,1);
      const on = line>.30?1:0; const v2=.12+.10*(1-far);
      r=on?74:v2*40; g2=on?196*det+34:v2*100; b2=on?244:v2*172;
    }
    const hazeK = far*far*.85;
    const hc = bp? [40,120,190] : [G[0]*.5+70, G[1]*.5+60, G[2]*.5+70];
    r+=(hc[0]-r)*hazeK; g2+=(hc[1]-g2)*hazeK; b2+=(hc[2]-b2)*hazeK;
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255);
    px[o+3]=255*AL*cl(1-far*far*.72,0,1)*cl(dy/2.2,0,1);
  }
}
